function recordKey(record:Pick<WorkspaceRecord,'family'|'id'>){return `${record.family}:${record.id}`}
function mergeRecords(previous:WorkspaceRecord[],incoming:WorkspaceRecord[]){const values=new Map(previous.map(record=>[recordKey(record),record]));for(const record of incoming){const old=values.get(recordKey(record));if(!old||record.rev>=old.rev)values.set(recordKey(record),record)}return Array.from(values.values())}
