function recordUrl(record:WorkspaceRecord){return `/?view=${viewForFamily(record.family)}&family=${record.family}&id=${encodeURIComponent(record.id)}`}
function isLinked(a:WorkspaceRecord,b:WorkspaceRecord){return a.links.some(l=>l.id===b.id&&l.family===b.family)||b.links.some(l=>l.id===a.id&&l.family===a.family)}
