function useReadingDisclosure(reduced:boolean){
 const disclosure=useRef<HTMLDetailsElement>(null),initialOpen=useRef(!reduced);
 useLayoutEffect(()=>{const node=disclosure.current;if(node){
  // GPT owners conditionally mount their native dialogs. Keep their ancestors
  // open before paint, including while showModal is still awaiting its effect.
  // A layout preference from another tab must never conceal an active modal.
  node.open=!reduced||!!node.querySelector('dialog');
 }},[reduced]);
 return {ref:disclosure,initialOpen:initialOpen.current};
}
